begin;
alter table public.companies enable row level security;
alter table public.filings enable row level security;
alter table public.financials enable row level security;
alter table public.source_refs enable row level security;
alter table public.adjustments enable row level security;
alter table public.shareholding enable row level security;
alter table public.review_queue enable row level security;
alter table public.eval_runs enable row level security;
alter table public.memos enable row level security;
revoke all on public.companies,public.filings,public.financials,public.source_refs,public.adjustments,public.shareholding,public.review_queue,public.eval_runs,public.memos from anon,authenticated;
grant select on public.companies,public.filings,public.financials,public.source_refs,public.adjustments,public.shareholding,public.eval_runs to anon,authenticated;
grant select,insert,update,delete on public.memos to authenticated;
grant all on public.companies,public.filings,public.financials,public.source_refs,public.adjustments,public.shareholding,public.review_queue,public.eval_runs,public.memos to service_role;
create policy published_companies on public.companies for select to anon,authenticated using (is_published);
create policy published_filings on public.filings for select to anon,authenticated using (exists(select 1 from public.companies c where c.id=company_id and c.is_published));
create policy published_financials on public.financials for select to anon,authenticated using (exists(select 1 from public.companies c where c.id=company_id and c.is_published));
create policy published_sources on public.source_refs for select to anon,authenticated using (exists(select 1 from public.companies c where c.id=company_id and c.is_published));
create policy published_adjustments on public.adjustments for select to anon,authenticated using (status='accepted' and exists(select 1 from public.companies c where c.id=company_id and c.is_published));
create policy published_shareholding on public.shareholding for select to anon,authenticated using (exists(select 1 from public.companies c where c.id=company_id and c.is_published));
create policy published_evals on public.eval_runs for select to anon,authenticated using (true);
create policy own_memos_select on public.memos for select to authenticated using ((select auth.uid())=user_id);
create policy own_memos_insert on public.memos for insert to authenticated with check ((select auth.uid())=user_id);
create policy own_memos_update on public.memos for update to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id);
create policy own_memos_delete on public.memos for delete to authenticated using ((select auth.uid())=user_id);
commit;
